<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue';import {ArrowUp,ArrowDown,Download,Refresh,Search} from '@element-plus/icons-vue';import {logFollowKey,clampLogHeight} from '../domain/controllers';import type {Workbench} from '../app/useWorkbench';const {w}=defineProps<{w:Workbench}>();const s=w.s;const area=ref<HTMLElement>();const lines=computed(()=>w.log.lines.filter(line=>!s.logSearch||line.toLowerCase().includes(s.logSearch.toLowerCase())));const errors=computed(()=>w.log.lines.filter(line=>/ERROR|FATAL/i.test(line)).length);const visibleCount=computed(()=>lines.value.length);
watch(()=>logFollowKey(w.log),async()=>{if(s.logFollow){await nextTick();if(area.value)area.value.scrollTop=area.value.scrollHeight;}});
function resize(event:PointerEvent){const start=event.clientY,initial=s.logHeight;const move=(e:PointerEvent)=>s.logHeight=clampLogHeight(initial+start-e.clientY,window.innerHeight);const done=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',done);};window.addEventListener('pointermove',move);window.addEventListener('pointerup',done);}
</script>
<template><section class="log-drawer" data-testid="log-drawer" :class="{open:s.logOpen}" :style="{height:(s.logOpen?s.logHeight:40)+'px'}"><div v-if="s.logOpen" class="log-resizer" @pointerdown="resize"/><header class="log-header"><button class="log-toggle" @click="s.logOpen=!s.logOpen"><el-icon><ArrowDown v-if="s.logOpen"/><ArrowUp v-else/></el-icon><strong>任务日志</strong><span v-if="w.log.sid" class="log-sid">SID {{w.log.sid}}</span></button><span class="log-connection"><i :class="{working:s.runtime.busy}"/>{{s.logStatus}}</span><span class="log-errors">{{errors}} 错误</span><span class="log-lines">{{visibleCount}} 行<span v-if="w.log.dropped"> · 已折叠早期 {{w.log.dropped}} 行</span></span><div v-if="s.logOpen" class="log-tools"><el-input v-model="s.logSearch" :prefix-icon="Search" placeholder="查找日志" size="small" clearable/><el-checkbox v-model="s.logFollow" size="small">跟随</el-checkbox><el-button :icon="Refresh" size="small" text @click="w.resumeLog" title="补读日志"/><el-button :icon="Download" size="small" text @click="w.exportLog" :disabled="!w.log.sid||!!s.pending">完整另存为</el-button></div></header><div v-if="s.logOpen" ref="area" class="log-content"><div v-if="!w.log.lines.length" class="log-empty">{{w.log.sid?'等待会话输出…':'运行、编译或查看历史会话后，日志将显示在这里。'}}</div><div v-for="(line,index) in lines" :key="index" :class="/FATAL|ERROR/.test(line)?'log-error':/WARN/.test(line)?'log-warning':''"><span class="log-line-number">{{w.log.dropped+index+1}}</span>{{line}}</div></div></section></template>
